package com.catcore.ctrlmietze.multitask; import android.os.*; import android.widget.*; import androidx.appcompat.app.AppCompatActivity; public final class LaunchProxyActivity extends AppCompatActivity { public static final String EXTRA_PACKAGE="target_package",EXTRA_ACTIVITY="target_activity"; protected void onCreate(Bundle b){super.onCreate(b);String p=getIntent().getStringExtra(EXTRA_PACKAGE),a=getIntent().getStringExtra(EXTRA_ACTIVITY);if(p==null||a==null){finish();return;}TaskLauncher.launchNewTask(this,p,a,(ok,m)->{Toast.makeText(this,m,Toast.LENGTH_SHORT).show();finish();});}}
